from typing import List, Dict, Any
import csv
import io
import re
from collections import deque

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    if not text.strip():
        return {"columns": [], "rows": []}

    lines = text.split("\n")

    def split_fields(line: str) -> List[str]:
        try:
            return next(csv.reader([line], delimiter=",", quotechar='"', escapechar=None, doublequote=True, skipinitialspace=False))
        except Exception:
            return line.split(",")

    def is_data_like(fields: List[str]) -> bool:
        if not fields:
            return False
        joined = ",".join(fields)
        return bool(re.search(r"\d{1,2}/\d{1,2}/\d{2,4}", joined) or re.search(r"\$\d", joined) or re.search(r"\d{2}:\d{2}", joined))

    # Find header line
    header_idx = None
    header_fields = None
    for i, line in enumerate(lines):
        if not line.strip():
            continue
        fields = split_fields(line)
        if len(fields) >= 2 and not is_data_like(fields):
            header_idx = i
            header_fields = fields
            break

    if header_idx is None:
        # Fallback: parse everything as rows
        reader = csv.reader(io.StringIO(text), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
        rows = [row for row in reader if any(cell != "" for cell in row)]
        if not rows:
            return {"columns": [], "rows": []}
        width = max(len(r) for r in rows)
        rows = [r + [""] * (width - len(r)) for r in rows]
        return {"columns": rows[0], "rows": rows[1:]}

    # Parse logical rows from header onward, preserving quoted newlines
    remainder = "\n".join(lines[header_idx:])
    reader = csv.reader(io.StringIO(remainder), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)

    parsed_rows = []
    for row in reader:
        if not row or all(cell == "" for cell in row):
            continue
        parsed_rows.append([str(cell) for cell in row])

    if not parsed_rows:
        return {"columns": header_fields or [], "rows": []}

    columns = parsed_rows[0]
    data_rows = parsed_rows[1:]

    width = max([len(columns)] + [len(r) for r in data_rows]) if data_rows else len(columns)
    if len(columns) < width:
        columns = columns + [""] * (width - len(columns))

    normalized_rows = []
    for row in data_rows:
        if len(row) < width:
            row = row + [""] * (width - len(row))
        elif len(row) > width:
            row = row[:width]
        normalized_rows.append(row)

    return {"columns": columns, "rows": normalized_rows}
